"""Tiny wc. Usage: python wc.py [--lines] [--words] [--chars] [--top N] FILE"""
import argparse
import sys
from collections import Counter


def count(text):
    return {
        "lines": len(text.splitlines()),
        "words": len(text.split()),
        "chars": len(text),
    }


def main(argv=None):
    ap = argparse.ArgumentParser()
    ap.add_argument("file")
    ap.add_argument("--lines", action="store_true")
    ap.add_argument("--words", action="store_true")
    ap.add_argument("--chars", action="store_true")
    ap.add_argument("--top", type=int, metavar="N")
    a = ap.parse_args(argv)
    with open(a.file) as f:
        text = f.read()
    c = count(text)
    if a.top is not None:
        for word, n in Counter(text.split()).most_common(a.top):
            print(f"{word} {n}")
    else:
        selected = [
            k for k in ("lines", "words", "chars") if getattr(a, k)
        ] or ["lines", "words"]
        for k in selected:
            print(f"{k} {c[k]}")
    return 0


if __name__ == "__main__":
    sys.exit(main())

